import{_ as r,o as a,c as e,ag as d}from"./chunks/framework.Aev9KvMf.js";const c=JSON.parse('{"title":"GB 7718 预包装食品标签通则 · 配料表与日期怎么看","description":"国标科普：GB 7718 预包装食品标签的强制内容、配料表递减读法、日期标示，含 2025 新版要点（致敏物质、数字标签、\\"零添加\\"用语管理）。","frontmatter":{"title":"GB 7718 预包装食品标签通则 · 配料表与日期怎么看","issuer":"国家卫生健康委 / 国家市场监督管理总局","source_tier":"一级来源","version":"现行 GB 7718—2011；新版 GB 7718—2025 已发布（2027-03-16 实施）","published":"2025-03","source_url":"https://openstd.samr.gov.cn/bzgk/gb/std_list?p.p2=7718","status":"现行（2027-03-16 起由 GB 7718—2025 替代）","tags":["国标","食品标签","配料表","保质期","行动清单"],"type":"国标科普","reviewed":false,"description":"国标科普：GB 7718 预包装食品标签的强制内容、配料表递减读法、日期标示，含 2025 新版要点（致敏物质、数字标签、\\"零添加\\"用语管理）。"},"headers":[],"relativePath":"standards/gb7718-food-label.md","filePath":"standards/gb7718-food-label.md"}'),o={name:"standards/gb7718-food-label.md"};function s(l,t,n,h,g,i){return a(),e("div",null,[...t[0]||(t[0]=[d('<h1 id="gb-7718-预包装食品标签通则-·-配料表与日期怎么看" tabindex="-1">GB 7718 预包装食品标签通则 · 配料表与日期怎么看 <a class="header-anchor" href="#gb-7718-预包装食品标签通则-·-配料表与日期怎么看" aria-label="Permalink to &quot;GB 7718 预包装食品标签通则 · 配料表与日期怎么看&quot;">​</a></h1><div class="warning custom-block"><p class="custom-block-title">初稿待人工校验</p><p>本页由 AI 依据标准公开信息与官方问答整理，尚未逐条对照原文校验；校验通过前请以标准原文和官方问答为准。</p></div><div class="danger custom-block"><p class="custom-block-title">使用须知</p><p>本页内容<strong>整理自国家标准与官方发布信息</strong>；标注【本站提示】的少数条目为中性工具提示。本站不构成诊疗建议。</p></div><blockquote><p><strong>标准出处</strong>：GB 7718《食品安全国家标准 预包装食品标签通则》（<a href="https://openstd.samr.gov.cn/bzgk/gb/std_list?p.p2=7718" target="_blank" rel="noreferrer">国家标准全文公开系统查询</a>）· 一级来源。现行版本 GB 7718—2011；<strong>新版 GB 7718—2025 已于 2025 年 3 月 16 日发布，2027 年 3 月 16 日实施</strong>（<a href="https://www.nhc.gov.cn/sps/c100087/202509/470fa4ff5de14dd38619223cce9da4e7.shtml" target="_blank" rel="noreferrer">国家卫健委问答</a>）。</p></blockquote><h2 id="速览卡" tabindex="-1">速览卡 <a class="header-anchor" href="#速览卡" aria-label="Permalink to &quot;速览卡&quot;">​</a></h2><p>预包装食品的包装上，标准强制要求让你看到：<strong>食品名称、配料表、净含量、生产者信息、生产日期与保质期、贮存条件</strong>等。看包装先看这三样：<strong>配料表（按加入量递减排序）、生产日期、保质期</strong>。</p><h2 id="核心要点-现行-2011-版" tabindex="-1">核心要点（现行 2011 版） <a class="header-anchor" href="#核心要点-现行-2011-版" aria-label="Permalink to &quot;核心要点（现行 2011 版）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>要点</th><th>内容</th><th>出处</th></tr></thead><tbody><tr><td>强制标示</td><td>食品名称、配料表、净含量规格、生产者/经销者信息、生产日期、保质期、贮存条件、生产许可证编号等</td><td><a href="https://openstd.samr.gov.cn/bzgk/gb/std_list?p.p2=7718" target="_blank" rel="noreferrer">标准正文</a></td></tr><tr><td>配料表排序</td><td>按<strong>加入量递减</strong>排列——排位越靠前含量越高</td><td><a href="https://openstd.samr.gov.cn/bzgk/gb/std_list?p.p2=7718" target="_blank" rel="noreferrer">标准正文</a></td></tr><tr><td>日期</td><td>生产日期与保质期必须清晰标示；保质期指&quot;最佳食用期限&quot;</td><td><a href="https://openstd.samr.gov.cn/bzgk/gb/std_list?p.p2=7718" target="_blank" rel="noreferrer">标准正文</a></td></tr></tbody></table><h2 id="新版-gb-7718—2025-要点-·-待逐条核验" tabindex="-1">新版（GB 7718—2025）要点 · 待逐条核验 <a class="header-anchor" href="#新版-gb-7718—2025-要点-·-待逐条核验" aria-label="Permalink to &quot;新版（GB 7718—2025）要点 · 待逐条核验&quot;">​</a></h2><ul><li><strong>致敏物质</strong>标示要求强化（含麸质谷物、甲壳纲、鱼、蛋、花生、大豆、乳、坚果等推荐/强制标注方向）。</li><li><strong>日期标示</strong>调整：统一&quot;保质期到期日&quot;表述方向。</li><li><strong>数字标签</strong>：鼓励用二维码等数字化方式扩展标签信息。</li><li>对&quot;<strong>零添加</strong>&quot;&quot;<strong>不添加</strong>&quot;等用语的管控（与同期发布的《食品标识监督管理办法》衔接）。</li><li>以上变化方向据官方发布与解读，具体条款以标准原文和<a href="https://www.nhc.gov.cn/sps/c100087/202509/bc824a504ec34c27883da73f14c20d44.shtml" target="_blank" rel="noreferrer">官方问答</a>为准。</li><li>逐条对比：见<a href="/SageRelay/standards/gb7718-2025-preview.html">标签要变什么 · GB 7718-2025 新旧对比</a>（日期双标示、八大类致敏物质强制提示、数字标签规范）。</li></ul><h2 id="行动清单-看包装-30-秒" tabindex="-1">行动清单：看包装 30 秒 <a class="header-anchor" href="#行动清单-看包装-30-秒" aria-label="Permalink to &quot;行动清单：看包装 30 秒&quot;">​</a></h2><table tabindex="0"><thead><tr><th>怎么做</th><th>出处</th></tr></thead><tbody><tr><td>配料表前三位是什么，心里先有数（递减排序）</td><td><a href="https://openstd.samr.gov.cn/bzgk/gb/std_list?p.p2=7718" target="_blank" rel="noreferrer">标准正文</a></td></tr><tr><td>找生产日期与保质期，核对贮存条件（如&quot;冷藏&quot;却常温摆卖的要注意）</td><td><a href="https://openstd.samr.gov.cn/bzgk/gb/std_list?p.p2=7718" target="_blank" rel="noreferrer">标准正文</a></td></tr><tr><td>有过敏体质的家人：找致敏物质标注（2027 年新版实施后将更规范）</td><td><a href="https://www.nhc.gov.cn/sps/c100087/202509/470fa4ff5de14dd38619223cce9da4e7.shtml" target="_blank" rel="noreferrer">新版要点</a></td></tr><tr><td>营养信息去相邻的营养成分表看（见本站 <a href="/SageRelay/standards/gb28050-nutrition-label.html">GB 28050 词条</a>）</td><td>【本站提示】两标准配套使用</td></tr></tbody></table><h2 id="与本站的关系" tabindex="-1">与本站的关系 <a class="header-anchor" href="#与本站的关系" aria-label="Permalink to &quot;与本站的关系&quot;">​</a></h2><ul><li>配料表递减 + 营养成分表 = 买食品的两把尺子：本页管&quot;<strong>里面装了什么</strong>&quot;，<a href="/SageRelay/standards/gb28050-nutrition-label.html">GB 28050 词条</a>管&quot;<strong>营养多少</strong>&quot;。</li></ul><h2 id="原文与溯源" tabindex="-1">原文与溯源 <a class="header-anchor" href="#原文与溯源" aria-label="Permalink to &quot;原文与溯源&quot;">​</a></h2><table tabindex="0"><thead><tr><th>字段</th><th>内容</th></tr></thead><tbody><tr><td>标准号</td><td>GB 7718—2011（现行）；GB 7718—2025（已发布，2027-03-16 实施）</td></tr><tr><td>归口</td><td>国家卫生健康委（食品安全国家标准）</td></tr><tr><td>全文阅览</td><td><a href="https://openstd.samr.gov.cn/bzgk/gb/std_list?p.p2=7718" target="_blank" rel="noreferrer">国家标准全文公开系统</a></td></tr><tr><td>新版问答</td><td><a href="https://www.nhc.gov.cn/sps/c100087/202509/470fa4ff5de14dd38619223cce9da4e7.shtml" target="_blank" rel="noreferrer">国家卫健委标准问答</a></td></tr></tbody></table>',16)])])}const p=r(o,[["render",s]]);export{c as __pageData,p as default};
